Sug_Text:
I have met a problem about the title being described: "The guard statement breaks type inference" for some reason. I have created a `Playground` project to play around. 

Here are some boilerplate code for setup:

    import Foundation

    struct Model: Decodable {
        var i: String
    }

    let jsonString = """
    {
        "i": "yes"
    }
    """

    let jsonData = jsonString.data(using: .utf8)
    let theModel = try JSONDecoder().decode(Model.self, from: jsonData!)

    struct Response<T> {
        var decodedData: T?
    }

    enum Result<Value> {
        case success(Value)
        case failure
    }

    struct Client {
        static let shared = Client()
        private init() {}

        func execute<T: Decodable>(completion: (Response<T>) -> ()) {
            let decodedData = try! JSONDecoder().decode(T.self, from: jsonData!)
            completion(Response(decodedData: decodedData))
        }
    }


Here's the problem:


    struct ServicesA {
        func loadSomething(completion: (Result<Model>) -> ()) {
            Client.shared.execute { result in      // error: generic parameter 'T' could not be inferred
                guard let decodedData = data else { return }
                completion(Result.success(decodedData))
            }
        }
    }

    struct ServicesB {
        func loadSomething(completion: (Result<Model>) -> ()) {
            Client.shared.execute { result in
                completion(Result.success(result.decodedData!))
            }
        }
    }


As  you can see, the only difference is `guard let decodedData = data else { return }`. It breaks the type inference so that the `Client.shared.execute` function complains that the `T` can't be inferred.

I wonder why would this happen and what's the most appropriate way to deal with this issue?

ph_text:
I have met a problem like what title has described: the guard statement breaks type inference for some reason. I have created a `Playground` project to play around. 

Here are some boilerplate code for setup:

    import Foundation

    struct Model: Decodable {
        var i: String
    }

    let jsonString = """
    {
        "i": "yes"
    }
    """

    let jsonData = jsonString.data(using: .utf8)
    let theModel = try JSONDecoder().decode(Model.self, from: jsonData!)

    struct Response<T> {
        var decodedData: T?
    }

    enum Result<Value> {
        case success(Value)
        case failure
    }

    struct Client {
        static let shared = Client()
        private init() {}

        func execute<T: Decodable>(completion: (Response<T>) -> ()) {
            let decodedData = try! JSONDecoder().decode(T.self, from: jsonData!)
            completion(Response(decodedData: decodedData))
        }
    }


Here's the problem:


    struct ServicesA {
        func loadSomething(completion: (Result<Model>) -> ()) {
            Client.shared.execute { result in      // error: generic parameter 'T' could not be inferred
                guard let decodedData = data else { return }
                completion(Result.success(decodedData))
            }
        }
    }

    struct ServicesB {
        func loadSomething(completion: (Result<Model>) -> ()) {
            Client.shared.execute { result in
                completion(Result.success(result.decodedData!))
            }
        }
    }


As what you can see, the only difference is `guard let decodedData = data else { return }`. It breaks the type inference so that the `Client.shared.execute` function complains that the `T` can't be inferred.

I wonder why would this happen and what's the most appropriate way to deal with this issue.

