Sug_Text:
You do not need to make  a copy of `key`, you can just index into `key` modulo its length.

By the way, **NEVER EVER USE** [`strncpy`](http://www.tutorialspoint.com/c_standard_library/c_function_strncpy.htm), it does not do what you think it does, its semantics are error prone, it is never the right tool for the job.

Also do not define `string` with `typedef char *string;`, it is misleading and error prone, especially for people who know C++.  Just use `char *`, it makes your code much easier to read by C programmers.

Here is a simpler version:

    #include <stdio.h>
    #include <stdlib.h>
    #include <cs50.h>
    #include <string.h>
    #include <ctype.h>

    int main(int argc, char *argv[]) {
        int result;

        if (argc != 2) {
            printf("Shame on you!\n");
            return 1;
        }

        char *key = argv[1];
        int klen = strlen(key);
        char *text = GetString();

        // Main loop starts here
        for (int i = 0, n = strlen(text); i < n; i++) {
            result = text[i] + key[i % len];

            if (isupper((unsigned char)text[i]) && result > 'Z') {
                result = result - 26;
            }
            if (islower((unsigned char)text[i]) && result > 'z') {
                result = result - 26;
            }
            if (isalpha((unsigned char)text[i])) {
                printf("%c", result);
            } else {
                printf("%c", text[i]);
            }
        }
        printf("\n");
        return 0;
    }

HINT: your *vigenere* is incorrect, you should use `result = text[i] + key[i % len] - 'A';` if the `key` is all uppercase.

