Sug_Text:
Ok I am using **Johannes-Schaub-litb's** code.

    char * getline(char cp) {
        char * line = malloc(100), * linep = line;
        size_t lenmax = 100, len = lenmax;
        int c;


        if(line == NULL)
            return NULL;

        for(;;) {
            c = fgetc(stdin);
            if(c == EOF)
                break;

            if(--len == 0) {
                len = lenmax;
                char * linen = realloc(linep, lenmax *= 2);

                if(linen == NULL) {
                    free(linep);
                    return NULL;
                }
                line = linen + (line - linep);
                linep = linen;
            }

            if((*line++ = c) == cp)
                break;
        }
        *line = '\0';
        return linep;
    }

I'm still using this code and it works fine. It's really well written.

