    {
        char *word = (char *)malloc(sizeof(char) * 20);
        strcpy(word, "jon jones");

        node *sentence = (node*)malloc(sizeof(node)); // Initialize node area
        sentence->arr = word; 
        printf("%s", sentence->arr);

        free(word);
        free(sentence);
        return 0;
    }

