Use method according to your requirement:

    - (NSString *)timeFormatted:(float)totalSeconds
    {
       int seconds = totalSeconds % 60; 
       int minutes = (totalSeconds / 60) % 60; 
       int hours = totalSeconds / 3600; 
       return [NSString stringWithFormat:@"%02i:%02i:%02i",hours, minutes, seconds]; 
    }

Refer more on [this](http://stackoverflow.com/questions/5271521/how-to-lock-the-horizontal-scrolling-of-a-scrollview-in-ios) link.

