        else
        {
            /** Do sentry stuff */
            try
            {
                $activated = Input::get('activated') ? true : false;

                // Create the user
                $user = Sentry::createUser(array(
                    'username'  =>  Input::get('username'),
                    'email'     => Input::get('email'),
                    'password'  => Input::get('password'),
                    'activated' => $activated,
                ));

                $group = Sentry::findGroupById(Input::get('group'));
                $user->addGroup($group);
            }
            catch (Cartalyst\Sentry\Users\LoginRequiredException $e)
            {
                $message[] = 'Login field is required.';
            }
            catch (Cartalyst\Sentry\Users\PasswordRequiredException $e)
            {
                $message[] = 'Password field is required.';
            }
            catch (Cartalyst\Sentry\Users\UserExistsException $e)
            {
                $message[] = 'User with this login already exists.';
            }
            catch (Cartalyst\Sentry\Groups\GroupNotFoundException $e)
            {
                $message[] = 'Group was not found.';
            }



            if(isset($message))
                return Redirect::route('addUser')
                    ->withErrors($message)
                    ->withInput(Input::except(['password', 'password_confirmation']));
            else
            {
                $message = 'User has been added';
                return Redirect::route('addUser')
                    ->with('success', $message);
            }
        }
    }
    return $this->render('admin/users/add');

Now, as the exception is thrown I would have assumed the user would not be created, however I can't figure out why it is.

Is there a specific way or another way that I am missing in which to only register the user if no exceptions are thrown?

