Its not a best practice to make the XHR call within the controller. Separate it out in a factory and take care not to repeate the call If you have data available. Your service should have a full control over when to hit the server to fetch data. Controllers should only access the service.

I would probably do this:

    App.factory('eywa', ['$http', function($http) {
      var eywaFactory = {};

      eywaFactory.data = '';
      eywaFactory.load = function() {
        this.data = $http.get('./assets/js/angularxml/courseDef.xml').then(function(data) {
          return x2js.xml_str2json(data);
        });
        return this.data;
      };

      eywaFactory.get = function() {
        return this.data === '' ? this.load() : this.data;
      };

      return eywaFactory;
    }]);

And call the service inside controller:


    App.controller('MainCtrl', function($scope, eywa) { 
        eywa.get().then(function(data) {
          $scope.courseDef = data;
        });
    });

Sug_Text:
`then()` basically adds a new navigation step in a stack. A step is a javascript function  which can do two different things:

1. waiting for the previous step - if any - being executed
2. waiting for a requested url and related page to load

Let's take a simple navigation scenario:

    var casper = require('casper').create();

    casper.start();

    casper.then(function step1() {
        this.echo('this is step one');
    });

    casper.then(function step2() {
        this.echo('this is step two');
    });

    casper.thenOpen('http://google.com/', function step3() {
        this.echo('this is step 3 (google.com is loaded)');
    });

You can print out all the created steps within the stack like this:

    require('utils').dump(casper.steps.map(function(step) {
        return step.toString();
    }));

That gives:

    $ casperjs test-steps.js
    [
        "function step1() { this.echo('this is step one'); }",
        "function step2() { this.echo('this is step two'); }",
        "function _step() { this.open(location, settings); }",
        "function step3() { this.echo('this is step 3 (google.com is loaded)'); }"
    ]

Notice the `_step()` function which has been added automatically by CasperJS to load the url for us; when the url is loaded, the next step available in the stack ‚Äî which is `step3()` ‚Äî is called.

When you have defined your navigation steps, `run()` executes them one by one sequentially:

    casper.run();

**Footnote:** the callback/listener stuff is an implementation of the [Promise pattern](http://blog.thepete.net/blog/2011/07/02/javascript-promises/).

