$hours = floor($seconds / 3600);
$mins = floor(($seconds - ($hours*3600)) / 60);

// added function containing the above code
// returning the output in the format 22:12:12
function get_time($seconds)
{
    $hours = floor($seconds / 3600);
    $mins = floor(($seconds - ($hours*3600)) / 60);
    $secs = floor($seconds - (($hours * 3600) + ($mins * 60)));
    return str_pad($hours, 2, '0', STR_PAD_LEFT) 
           . ':' . str_pad($mins, 2, '0', STR_PAD_LEFT) 
           . ':' . str_pad($secs, 2, '0', STR_PAD_LEFT);
}

xilvar's answer is very nice, but had two minor shortcomings that I wanted to fix in a rejected edit, so I'll post it as an answer.

For one, xilvar's solution fails if the file is a JPEG or there's no exif data present. And for the other, it always rotated 180 degrees instead of the appropriate amount.

    from PIL import Image, ExifTags

    try:
        image=Image.open(os.path.join(path, fileName))
        if hasattr(image, '_getexif'): # only present in JPEGs
            for orientation in ExifTags.TAGS.keys(): 
                if ExifTags.TAGS[orientation]=='Orientation':
                    break 
            e = image._getexif()       # returns None if no EXIF data
            if e is not None:
                exif=dict(e.items())
                orientation = exif[orientation] 

                if orientation == 3:   image = image.transpose(Image.ROTATE_180)
                elif orientation == 6: image = image.transpose(Image.ROTATE_270)
                elif orientation == 8: image = image.transpose(Image.ROTATE_90)

        image.thumbnail((THUMB_WIDTH , THUMB_HIGHT), Image.ANTIALIAS)
        image.save(os.path.join(path,fileName))

    except:
        traceback.print_exc()

ph_text:
xilvar's answer is very nice, but had two minor shortcomings that I wanted to fix in a rejected edit, so I'll post it as an answer.

For one, xilvar's solution fails if the file is a JPEG or there's no exif data present. And for the other, it always rotated 180 degrees instead of the appropriate amount.

    import Image, ExifTags

    try:
        image=Image.open(os.path.join(path, fileName))
        if hasattr(image, '_getexif'): # only present in JPEGs
            for orientation in ExifTags.TAGS.keys(): 
                if ExifTags.TAGS[orientation]=='Orientation':
                    break 
            e = image._getexif()       # returns None if no EXIF data
            if e is not None:
                exif=dict(e.items())
                orientation = exif[orientation] 

                if orientation == 3:   image = image.transpose(Image.ROTATE_180)
                elif orientation == 6: image = image.transpose(Image.ROTATE_270)
                elif orientation == 8: image = image.transpose(Image.ROTATE_90)

        image.thumbnail((THUMB_WIDTH , THUMB_HIGHT), Image.ANTIALIAS)
        image.save(os.path.join(path,fileName))

    except:
        traceback.print_exc()

