Ok, i strongly recommend to use AChartEngine, it is free, lightweight and supports many types of charts pie, graph etc.As about to dinamically update the chart i achieved this by adding values in a separate thread.Here is my example,it is nothing fancy:

    package my.pack;

    import java.util.Date;
    import java.util.Random;

    import org.achartengine.ChartFactory;
    import org.achartengine.GraphicalView;
    import org.achartengine.chart.PointStyle;
    import org.achartengine.model.TimeSeries;
    import org.achartengine.model.XYMultipleSeriesDataset;
    import org.achartengine.renderer.XYMultipleSeriesRenderer;
    import org.achartengine.renderer.XYSeriesRenderer;

    import android.app.Activity;
    import android.graphics.Color;
    import android.os.Bundle;

     public class ChartsActivity extends Activity {

	private static Random random = new Random();

	private static TimeSeries timeSeries;
	private static XYMultipleSeriesDataset dataset;
	private static XYMultipleSeriesRenderer renderer;
	private static XYSeriesRenderer rendererSeries;
    private static GraphicalView view;


    @Override
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);     

        dataset = new XYMultipleSeriesDataset();

        renderer = new XYMultipleSeriesRenderer();
        renderer.setAxesColor(Color.BLUE);
        renderer.setAxisTitleTextSize(16);
        renderer.setChartTitle("Time");
        renderer.setChartTitleTextSize(15);
        renderer.setFitLegend(true);
        renderer.setGridColor(Color.LTGRAY);
        renderer.setPanEnabled(true, true);
        renderer.setPointSize(10);
        renderer.setXTitle("Time");
        renderer.setYTitle("Number");
        renderer.setMargins( new int []{20, 30, 15, 0});
        renderer.setZoomButtonsVisible(true);
        renderer.setBarSpacing(10);
        renderer.setShowGrid(true);


        rendererSeries = new XYSeriesRenderer();
        rendererSeries.setColor(Color.RED);
        renderer.addSeriesRenderer(rendererSeries);
        rendererSeries.setFillPoints(true);
        rendererSeries.setPointStyle(PointStyle.CIRCLE);

        timeSeries = new TimeSeries("Random");

		new AsyncTask<Void, Void, Void>() {

			@Override
			protected Void doInBackground(Void... params) {
				while(true){
	        		try {
						Thread.sleep(2000L);
					} catch (InterruptedException e) {
						e.printStackTrace();
					}

	        		// Execute on UI thread
                	publishProgress();
        		}
			}

			@Override
			protected void onProgressUpdate(Void... values) {
				timeSeries.add(new Date(), random.nextInt(10));
            	view.repaint();
			}

		}.execute();

	}
    }

	@Override
	protected void onStart() {
		super.onStart();
		dataset.addSeries(timeSeries);
		view = ChartFactory.getTimeChartView(this, dataset, renderer, "Test");
		view.refreshDrawableState();
		view.repaint();
		setContentView(view);	 
	}

}
Add your own values to the thread.You may want to take a look on how to use the AChartEngine library.
Happy coding!

