                      $('.columised').wrapAll('<section id="who-we-are" class="clearfix" />');
                      $('.columised').css({'width': windowWidth, 'float':'left' });
                      $('#who-we-are').after('<div class="clear"></div>');

                       $('.back-button').click(function(){
                              hideSubpage();
                      });

                      // sub content
                      $('.next-button').click(function(){
                              displaySubpage();
                      });
      });


                      function displaySubpage() {

                              updatePos('#who-we-are' , function(){
                                      $('body, html').css({'overflow':'hidden'});
                                      $('.mover').animate({
                                              'right': '100%'
                                      }, 1000);
                              });
                      }

                function hideSubpage() {
                              $('.mover').animate({
                                      'left': '0%'
                              },  1000, function(){ 
                                      $('body, html').css({'overflow':'auto'});
                              });
                      }


                function updatePos(target, callback){

                    var destination = $(target).offset().top;
                    var timeValue = 2000;

                    $("html:not(:animated),body:not(:animated)").stop(true, true).animate(
                      {scrollTop: destination},  2000, callback);

                return false;
        }    
      })(jQuery);

