Sug_Text:
UPDATE.

Here is a [simple and **tested** livereload solution][1] based on `connect` server and `connect-livereload` and `gulp-livereload` plugins,
that **does not need any browser extension nor any extra script tag in your file**:

<pre><code>
var gulp = require('gulp');
var connect = require('connect');
var connectLivereload = require('connect-livereload');
var opn = require('opn');
var gulpLivereload = require('gulp-livereload');

var config = {
	rootDir: __dirname,
	servingPort: 8080,

	// the files you want to watch for changes for live reload
	filesToWatch: ['*.{html,css,js}', '!Gulpfile.js']
}

// The default task - called when you run `gulp` from CLI
gulp.task('default', ['watch', 'serve']);

gulp.task('watch', ['connect'], function () {
  gulpLivereload.listen();
  gulp.watch(config.filesToWatch, function(file) {
    gulp.src(file.path)
      .pipe(gulpLivereload());
  });
});

gulp.task('serve', ['connect'], function () {
  return opn('http://localhost:' + config.servingPort);
});

gulp.task('connect', function(){
  return connect()
    .use(connectLivereload())
    .use(connect.static(config.rootDir))
    .listen(config.servingPort);
});
</code>
</pre>


---
If you're using `gulp-livereload`, I think there is no point in using `tiny-lr` as well.

You can find a working example of LiveReload integration here:

[https://github.com/kriasoft/spa-seed.front-end][2] - SPA Front-end Starter Kit

  [1]: https://github.com/dmitriz/gulp-automation
  [2]: https://github.com/kriasoft/spa-seed.front-end

