ph_text:
check this code for find index of given character as Int

    extension String {
    public func findIndexOfCharacter(char: Character) -> Int? {
        if let idx = string.characters.indexOf(char) {
            return string.startIndex.distanceTo(idx)
        }
        return nil
      }
    }

