Go from left to right. Remember the first peak, find a higher peak (or a same height one), then draw a lake between them, than remember this higher peak and repeat the process.
Then do the same going right to left. Its as simple as that. (Code is untested)

    def island_lakes():
        lst=[]
        x=[int(i) for i in sys.stdin.readline().split()]
        lst.extend(x)

        print(lst)       

     cur_height = lst[0]
     valley_found = false
     for i in range(1, len(lst)):
      if lst[i] >= cur_height and valley_found:
       print(cur_height)
       valley_found = false
      else:
       valley_found = true

      if lst[i] >= cur_height:
       cur_height = lst[i]

     cur_height = lst[-1]
     valley_found = false
     for i in range(len(lst)-2, -1, -1):
      if lst[i] >= cur_height and valley_found:
       print(cur_height)
       valley_found = false
      else:
       valley_found = true

      if lst[i] >= cur_height:
