Create a method that is called to send a batch of whatever size you need using the `slice` method on the array, call it manually once, then have your ajax return call it again if there are more records:

    // obviously don't use globals in *your* code...
    var current_count = 0;
    var batch_size = 100;
    var multiple = [{ "Author": "Sample Text" }, { "Author": "Second Sample Text" }... ];
    var end_index = multiple.length() - 1;

    function send_batch() {
       var batch_end = (current_count + batch_size) < end_index ? current_count + batch_size : end_index;
       var batch = multiple.slice(current_count, batch_end);
       current_count = batch_end;
       $.ajax({
         type: "POST",
         url: 'http://api.cloudservice.com/v1/your-api-key-here/Books',
         headers: { "Authorization": "Bearer your-access-token-here" },
         contentType: "application/json",
         data: JSON.stringify(batch)
        })
        .done(function (data) {
          //process data returned
        })
        .fail(function (error) {...})
        .always(function(data){
          if (batch_end <= end_index) {
            send_batch();
          }
        });
    };

You can pull out the Ajax call and parameterize things to make it more generic, but hopefully you'll get the idea.

ph_text:
Create a method that is called to send a batch of whatever size you need using the `slice` method on the array, call it manually once, then have your ajax return call it again if there are more records:

    // obviously don't use globals in *your* code...
    var current_count = 0;
    var batch_size = 100;
    var multiple = [{ "Author": "Sample Text" }, { "Author": "Second Sample Text" }... ];
    var end_index = multiple.length() - 1;

    function send_batch() {
       var batch_end = (current_count + batch_size) < end_index ? current_count + batch_size : end_index;
       var batch = multiple.slice(current_count, batch_end);
       current_count = batch_end;
       $.ajax({
         type: "POST",
         url: 'http://api.cloudservice.com/v1/your-api-key-here/Books',
         headers: { "Authorization": "Bearer your-access-token-here" },
         contentType: "application/json",
         data: JSON.stringify(batch),
         success: function (data) {
            if (batch_end <= end_index) {
